package worker

import (
  "log"
  "time"
)

type Job struct {
  ID      string
  Tenant  string
  Payload []byte
}

func Run(job Job, process func([]byte) error) {
  start := time.Now()
  log.Printf("job %s started tenant=%s", job.ID, job.Tenant)
  if err := process(job.Payload); err != nil {
    log.Printf("job %s failed tenant=%s: %v", job.ID, job.Tenant, err)
    return
  }
  log.Printf("job %s done tenant=%s took=%s", job.ID, job.Tenant, time.Since(start))
}

