func Run(job Job, process func([]byte) error) {
  logger := slog.With("job_id", job.ID, "tenant", job.Tenant)
  start := time.Now()
  logger.Info("job started")
  if err := process(job.Payload); err != nil {
    logger.Error("job failed", "err", err)
    return
  }
  logger.Info("job done", slog.Int64("took_ms", time.Since(start).Milliseconds()))
}
